from fractions import Fraction as Q
def st(*v):return list(map(str,v))
def noisy(t):
    t=Q(t);hi=str((1+t)/4);lo=str((1-t)/4);return [hi,lo,lo,hi]*3+[lo,hi,hi,lo]
S=[]
def spec(kind,cases,anchors,review,support,unpaid,names,colours,predicates,hyp,equations):
    gens=[{'id':name,'ordered_inputs':[colours[i]],'output':colours[i+1],'arity':1,'carrier':'Declared '+colours[i],'coefficient_ring':'Exact Q (Gaussian pairs where stated), integers and literal Boolean fields only','hypotheses':[hyp],'semantic_predicate':predicates[i]} for i,name in enumerate(names)]
    comps=[{'outer_operation':names[i+1],'input_slot':0,'inner_operation':names[i]} for i in range(2)]
    S.append(dict(kind=kind,cases=cases,anchors=anchors,review=review,support=support,unpaid=unpaid,gens=gens,comps=comps,equations=equations))

